// Loaded from inside a function (apiBoot()), so the globals are declared.
global $Servers, $dateTimeFormatter;
$Servers = array();

// The logger stamps lines with this (config.php makes an IntlDateFormatter).
$dateTimeFormatter = new class {
  public function format($time) { return gmdate('Y-m-d H:i:s', $time); }
};

